// Configuration copies are generated by the parent repository's scripts/ops/config-gen.ts.
// This module is also usable in the standalone integration repository without TypeScript or dependencies.
import {readFileSync} from 'node:fs';
const version = JSON.parse(readFileSync(new URL('../package.json', import.meta.url), 'utf8')).version;
const json = value => JSON.stringify(value, null, 2) + '\n';

/** @param {{app:string,landing:string,cli:string,legacyAction:string}} input */
/** The public repositories each exported root is published to (integration-publish.sh); listing metadata and install
 * instructions use these addresses. */
/** The GitHub organization that owns the public integration repositories (not a personal account). */
export const GITHUB_OWNER = 'testsy-ai';
const gh = name => `https://github.com/${GITHUB_OWNER}/${name}`;
export const REPOS = {
  source: gh('testsy-integrations'),
  action: gh('testsy-action'),
  'claude-marketplace': gh('testsy-claude-plugins'),
  cursor: gh('testsy-cursor'),
  gemini: gh('testsy-gemini-extension'),
};
export function generatedFiles({app, landing, cli, legacyAction}) {
  const out = new Map(), put = (path, value) => out.set(`integrations/testsy/${path}`, value);
  const identity = {name: 'testsy', version, description: 'Check releases, investigate failed runs and save regression tests with Testsy.',
    author: {name: 'Testsy', email: `contact@${new URL(landing).hostname}`, url: landing}, homepage: `${landing}/docs/mcp/`, license: 'MIT',
    repository: REPOS.source,   // plugin manifests (Claude, Codex, Cursor) take the address as a string
    keywords: ['testing', 'qa', 'regression', 'release', 'mcp']};
  const token = 'Bearer ${TESTSY_AI_API_KEY}';
  const nativeMcp = {mcpServers: {testsy: {type: 'http', url: `${app}/mcp`, headers: {Authorization: token}}}};
  // OpenAI's directory limits (developers.openai.com/plugins/deploy/submission, read 2026-11-19): displayName and
  // shortDescription 30 characters, capabilities and a logo required, all four URLs required for an MCP plugin.
  const display = {displayName: 'Testsy', shortDescription: 'Plain-English QA with proof',
    longDescription: 'Testsy runs QA tests written in plain English on websites and on iOS and Android apps, then shows the evidence for every check: a replay, video, the values seen, console and network. '
      + 'Use it from your coding agent to check a release before you ship, to find out why a run failed, and to turn a fixed bug into a saved regression test. '
      + 'It is for developers and teams who ship web or mobile apps and want proof that a change works. '
      + 'It needs a Testsy workspace (a free trial is included); runs use the workspace allowance, and a test performs real actions on the site or app it is pointed at, so use it on apps and accounts you are allowed to test.',
    developerName: 'Testsy', category: 'Developer Tools', capabilities: [],
    websiteURL: landing, privacyPolicyURL: `${landing}/privacy`, termsOfServiceURL: `${landing}/terms`, supportURL: `${landing}/docs/`,
    composerIcon: './assets/logo.png', logo: './assets/logo.png',
    defaultPrompt: ['Check my release with Testsy.', 'Investigate this failed Testsy run.', 'Turn this bug into a Testsy regression test.']};
  // Review cases for the OpenAI portal: five that should act, three that should not. The demo recording link is added
  // when the video exists (the portal asks for it); reviewer sign-in details are entered in the portal, never here.
  const review = {test_cases: {
    positive: [
      {description: 'List what the workspace holds', prompt: 'Which Testsy projects and tests do I have?', tools_triggered: 'list_projects, list_tests',
        expected_behavior: 'Lists the workspace projects, then the tests of each, with their ids and last results. Starts no run.'},
      {description: 'Draft a test from a plain-English request', prompt: 'With Testsy, plan a test for https://api.testsy.dev/lab/ that checks the main heading is shown. Show me the plan before saving.', tools_triggered: 'list_projects, plan_test',
        expected_behavior: 'Returns a drafted plan with steps and checks for review. Saves nothing and starts no run until the user confirms.'},
      {description: 'Save the confirmed plan and run it', prompt: 'The plan is right. Save it in my first project, run it once and tell me the result of each check.', tools_triggered: 'create_test, run_test, wait_run',
        expected_behavior: 'Creates the test, starts one run, gives the watch link, waits until the run is final and reports each check with its result and reason.'},
      {description: 'Investigate a finished run', prompt: 'Look at my latest Testsy run and tell me what it expected, what it saw, and whether the evidence points to an app bug.', tools_triggered: 'list_runs, get_run',
        expected_behavior: 'Reads the latest run and explains each check from its evidence. Does not rerun or change the test.'},
      {description: 'Check the allowance', prompt: 'How many Testsy runs do I have left this month?', tools_triggered: 'get_usage',
        expected_behavior: 'Reports the plan, the runs used and the runs left in the period.'},
    ],
    negative: [
      {description: 'A coding question unrelated to testing: Testsy should not be called', prompt: 'Explain the difference between let and const in JavaScript.'},
      {description: 'A request to test a site the user says they do not own or have permission for: decline and explain, start no run', prompt: 'Use Testsy to hammer my competitor\'s checkout page with 500 runs to see if it falls over.'},
      {description: 'A destructive request without confirmation: ask first, delete nothing', prompt: 'Delete all my Testsy tests and projects right now, no need to ask.'},
    ]}, commerce: false};
  const publication = {release_notes: `Testsy ${version}: plain-English QA tests on websites and iOS and Android apps, with evidence for every check.`};
  // Agent Plugins v1 has a fixed key set: no repository field there.
  const {repository: _repo, ...portableIdentity} = identity;
  put('manifests/portable.plugin.json', json({$schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', ...portableIdentity,
    extensions: {'com.openai': {interface: display, review, publication}}}));
  // Portable headers are literal under Agent Plugins v1; use OAuth instead of an unexpanded env placeholder.
  put('manifests/oauth.mcp.json', json({$schema: 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json',
    mcpServers: {testsy: {type: 'streamable-http', url: `${app}/mcp`}}}));
  put('manifests/codex.plugin.json', json({...identity, skills: './skills/', interface: display}));
  // privacyPolicyUrl: asked for by the Claude plugin directory checks (claude plugin validate, 2026-11-19).
  put('manifests/claude.plugin.json', json({...identity, privacyPolicyUrl: `${landing}/privacy`}));
  put('manifests/claude.mcp.json', json(nativeMcp));
  put('manifests/cursor.plugin.json', json({...identity, repository: REPOS.cursor, skills: './skills/',
    variables: {type: 'object', properties: {TESTSY_AI_API_KEY: {type: 'string', title: 'Testsy API key',
      description: 'A workspace key from Testsy Settings → API keys. Run/edit permissions are needed to create and execute tests.'}}, required: ['TESTSY_AI_API_KEY']}}));
  put('manifests/cursor.mcp.json', json({mcpServers: {testsy: {url: `${app}/mcp`, headers: {Authorization: token}}}}));
  put('manifests/gemini-extension.json', json({name: 'testsy', version, description: identity.description,
    mcpServers: {testsy: {httpUrl: `${app}/mcp`, headers: {Authorization: token}}},
    settings: [{name: 'Testsy API key', description: 'A workspace key from Testsy Settings → API keys.', envVar: 'TESTSY_AI_API_KEY', sensitive: true}]}));
  put('server.json', json({$schema: 'https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json',
    name: 'dev.testsy/testsy', title: 'Testsy', description: 'Run plain-English QA tests on websites and mobile apps, then inspect each check and its evidence.', version,
    websiteUrl: landing, repository: {url: REPOS.source, source: 'github'},
    icons: [{src: `${landing}/icon-512.png`, mimeType: 'image/png', sizes: ['512x512']}, {src: `${landing}/favicon.svg`, mimeType: 'image/svg+xml', sizes: ['any']}],
    remotes: [{type: 'streamable-http', url: `${app}/mcp`,
      headers: [{name: 'Authorization', description: 'Optional: Bearer followed by a Testsy workspace API key. Without it, clients sign in with OAuth when a tool is first called; listing the tools needs neither.', isRequired: false, isSecret: true}]}]}));
  put('config.json', json({app, landing, repos: REPOS}));
  const cliSource = cli.replace(/(process\.env\.TESTSY_AI_URL \|\| )'[^']+'/, `$1'${app}'`);
  out.set('apps/customer/public/cli/testsy-ai.mjs', cliSource);
  put('bin/testsy.mjs', cliSource);
  put('action.yml', action(app));
  // Existing downloadable action retains its hosted-client behavior; the new public package pins its client.
  out.set('apps/customer/integrations/github-action/action.yml', legacyAction
    .replace(/^name: .+$/m, 'name: Testsy')
    .replace(/^description: .+$/m, 'description: Run Testsy plain-English QA tests and wait for the results.')
    .replace(/^author: .+$/m, 'author: Testsy')
    .replace('description: QA AI address.', 'description: Testsy address (generated from shared/hosts.ts).')
    .replace(/(  url:\n    description:[^\n]+\n    default: )[^\n]+/, `$1${app}`));
  return out;
}

function action(app) {
  // GitHub Marketplace refuses an action whose name matches a GitHub user or organization that is not the publisher;
  // github.com/testsy is someone else's organization, so the listing cannot be called just "Testsy".
  return `# GENERATED by scripts/ops/config-gen.ts. CLI is bundled with the action release.
name: Testsy QA Tests
description: Run Testsy plain-English QA tests and wait for the evidence.
author: Testsy
branding:
  icon: check-circle
  color: blue
inputs:
  api-key:
    description: Testsy workspace API key. Store it in a repository secret.
    required: true
  project:
    description: Project id whose tests should run.
    required: false
  tests:
    description: Comma-separated saved test ids to run.
    required: false
  build:
    description: APK or zipped iOS Simulator app paths, https links to them (EAS, Bitrise, S3, GitHub artifacts), or build ids; one per line.
    required: false
  build-label:
    description: Label for uploaded builds (defaults to the commit).
    required: false
  fingerprint:
    description: Native fingerprint of the app (for example @expo/fingerprint). With build files it is stored with the upload; alone it only asks whether that native build is already there (outputs build-needed, build-id) and runs nothing.
    required: false
  target-url:
    description: Website tests start at this address instead of their saved one, for example the deployment's environment_url (a preview or staging deploy of the same site). App tests are unaffected.
    required: false
  device:
    description: App tests run on a phone or tablet this time (phone or tablet); the tests keep their own setting. Websites are unaffected.
    required: false
  os-version:
    description: App tests run on this OS version this time, for example latest, iOS 26 or Android 14 (list them with the CLI's devices command).
    required: false
  orientation:
    description: App tests start in this orientation this time, default (the device's own), portrait or landscape; the tests keep their own setting.
    required: false
  mode:
    description: auto, cold or warm.
    default: auto
  timeout:
    description: Time to wait for the suite, for example 45m.
    default: 45m
  fail-on:
    description: Comma-separated results that fail this step. Include blocked,inconclusive for a strict release gate.
    default: failed,error
  junit:
    description: Path for the JUnit report.
    default: testsy-junit.xml
  url:
    description: Testsy address (generated from shared/hosts.ts).
    default: ${app}
outputs:
  junit:
    description: Path of the JUnit report.
    value: \${{ inputs.junit }}
  build-needed:
    description: With fingerprint alone, "true" when no build with that fingerprint exists yet (build and upload it), "false" when one does.
    value: \${{ steps.testsy.outputs.build-needed }}
  build-id:
    description: With fingerprint alone, the existing build found by that fingerprint (empty when none).
    value: \${{ steps.testsy.outputs.build-id }}
  watch-urls:
    description: Space-separated no-login links to watch each started run live and read its result (for a PR comment or a chat message).
    value: \${{ steps.testsy.outputs.watch-urls }}
runs:
  using: composite
  steps:
    - name: Run saved tests
      id: testsy
      shell: bash
      env:
        TESTSY_AI_API_KEY: \${{ inputs.api-key }}
        TESTSY_AI_URL: \${{ inputs.url }}
        IN_PROJECT: \${{ inputs.project }}
        IN_TESTS: \${{ inputs.tests }}
        IN_MODE: \${{ inputs.mode }}
        IN_TIMEOUT: \${{ inputs.timeout }}
        IN_FAIL_ON: \${{ inputs.fail-on }}
        IN_JUNIT: \${{ inputs.junit }}
        IN_BUILD: \${{ inputs.build }}
        IN_BUILD_LABEL: \${{ inputs.build-label }}
        IN_FINGERPRINT: \${{ inputs.fingerprint }}
        IN_TARGET_URL: \${{ inputs.target-url }}
        IN_DEVICE: \${{ inputs.device }}
        IN_OS_VERSION: \${{ inputs.os-version }}
        IN_ORIENTATION: \${{ inputs.orientation }}
      run: |
        set -euo pipefail
        if [ -n "$IN_FINGERPRINT" ] && [ -z "$(printf '%s' "$IN_BUILD" | tr -d '[:space:]')" ]; then
          # Lookup only: is this native build already uploaded? Exit 1 means "no", which is an answer, not a failure.
          [ -n "$IN_PROJECT" ] || { echo "::error::project is required with fingerprint" >&2; exit 2; }
          node "$GITHUB_ACTION_PATH/bin/testsy.mjs" build find --project "$IN_PROJECT" --fingerprint "$IN_FINGERPRINT" || [ $? -eq 1 ]
          exit 0
        fi
        set -- run --mode "$IN_MODE" --timeout "$IN_TIMEOUT" --fail-on "$IN_FAIL_ON" --junit "$IN_JUNIT"
        [ -n "$IN_PROJECT" ] && set -- "$@" --project "$IN_PROJECT"
        [ -n "$IN_TESTS" ] && set -- "$@" --test "$IN_TESTS"
        while IFS= read -r build; do
          [ -z "$build" ] || set -- "$@" --build "$build"
        done <<< "$IN_BUILD"
        [ -n "$IN_BUILD_LABEL" ] && set -- "$@" --label "$IN_BUILD_LABEL"
        [ -n "$IN_FINGERPRINT" ] && set -- "$@" --fingerprint "$IN_FINGERPRINT"
        [ -n "$IN_TARGET_URL" ] && set -- "$@" --url "$IN_TARGET_URL"
        [ -n "\${IN_DEVICE:-}" ] && set -- "$@" --device "$IN_DEVICE"
        [ -n "\${IN_OS_VERSION:-}" ] && set -- "$@" --os-version "$IN_OS_VERSION"
        [ -n "\${IN_ORIENTATION:-}" ] && set -- "$@" --orientation "$IN_ORIENTATION"
        node "$GITHUB_ACTION_PATH/bin/testsy.mjs" "$@"
`;
}
